layer.css:
[data-ryt="pitch"] { color: rgb(161, 161, 170); background-color: rgba(255, 255, 255, 0.03); border-left: 4px solid var(--ryt-muted); border-radius: 0px 8px 8px 0px; font-family: var(--ryt-font-heading); font-size: 18.4px; font-weight: 400; font-style: italic; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(161, 161, 170); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 16px; padding-right: 24px; padding-bottom: 16px; padding-left: 24px; transition: all; border-top: none; border-right: none; border-bottom: none; position: relative }
[data-ryt="footer"] { color: rgb(161, 161, 170); border-top: 1px solid rgb(39, 39, 42); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-muted); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: 2px; transition: color 0.2s }
[data-ryt="section"] > h2 { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 800; font-style: normal; line-height: 1.3; letter-spacing: -0.72px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="brand"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 22.4px; font-weight: 800; font-style: normal; line-height: 1.7; letter-spacing: -0.448px; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: color 0.2s }
[data-ryt="header"] { border-bottom: 1px solid rgb(39, 39, 42); border-top: none }
[data-ryt="nav"] a { color: rgb(161, 161, 170); border-radius: 8px; font-family: var(--ryt-font-heading); font-size: 14.4px; font-weight: 500; font-style: normal; line-height: 1.7; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(161, 161, 170); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 7.2px; padding-right: 13.6px; padding-bottom: 7.2px; padding-left: 13.6px; transition: 0.2s; position: relative }
[data-ryt="button"] { color: var(--ryt-bg); background-color: var(--ryt-text); border-top: 1px solid var(--ryt-text); border-right: 1px solid var(--ryt-text); border-bottom: 1px solid var(--ryt-text); border-left: 1px solid var(--ryt-text); border-radius: 8px; font-family: var(--ryt-font-heading); font-weight: 500; font-style: normal; line-height: 1.7; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-bg); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 8px; padding-right: 16px; padding-bottom: 8px; padding-left: 16px; transition: 0.2s }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-muted); font-family: var(--ryt-font-heading); font-size: 12.8px; font-weight: 600; font-style: normal; line-height: 1.7; letter-spacing: 0.64px; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="cover"] { border-radius: 12px }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 800; font-style: normal; letter-spacing: -1.2px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: color 0.2s }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 34px; font-weight: 800; font-style: normal; line-height: 1.3; letter-spacing: -1.2px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { color: #60a5fa }
[data-ryt="cover"]:hover { opacity: 0.9 }
[data-ryt="button"]:hover { color: #60a5fa; background-color: rgba(37, 99, 235, 0.05); opacity: 0.9; background-color: #f4f4f5; color: #09090b }
[data-ryt="nav"] a::after { content: ""; display: block; position: absolute; width: 67.9844px; height: 2px; color: rgb(161, 161, 170); background-color: var(--ryt-muted); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 2px; font-family: var(--ryt-font-heading); font-size: 14.4px; font-weight: 500; font-style: normal; line-height: 1.7; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(161, 161, 170); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: transform 0.25s cubic-bezier(0.16, 1, 0.3, 1); -webkit-text-fill-color: rgb(161, 161, 170); bottom: 3.2px; left: 13.6px }
[data-ryt="nav"] a:hover { color: #60a5fa; color: #60a5fa; background-color: rgba(37, 99, 235, 0.06); color: #60a5fa; background-color: rgba(37, 99, 235, 0.06) }
[data-ryt="brand"]::before { content: ""; display: block; width: 16px; height: 16px; color: var(--ryt-text); background-color: var(--ryt-text); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 2px; font-family: var(--ryt-font-heading); font-size: 22.4px; font-weight: 800; font-style: normal; line-height: 1.7; letter-spacing: -0.448px; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; -webkit-text-fill-color: var(--ryt-text) }
[data-ryt="brand"]:hover { color: #60a5fa }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { color: #60a5fa; text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
[data-ryt="pitch"]::before { content: "“"; display: block; position: absolute; width: 53.3906px; height: 96px; color: var(--ryt-muted); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: serif; font-size: 96px; font-weight: 400; font-style: italic; line-height: 1; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; -webkit-text-fill-color: var(--ryt-muted); top: -10px; left: 10px }
